import { useParams, Link } from "react-router-dom";
import { useState, useEffect } from "react";
import Card from "../components/Card";

export default function RoadmapPage() {
  const { name } = useParams();

  const [domain, setDomain] = useState("");
  const [journeyStarted, setJourneyStarted] = useState(false);
  const [learningStarted, setLearningStarted] = useState(false);
  const [currentDay, setCurrentDay] = useState(1);

  const timeline = sessionStorage.getItem("timeline") || "3 months";

  // ✅ SESSION STATE
  useEffect(() => {
    const newDomain = name?.toLowerCase();
    const savedDomain = sessionStorage.getItem("selectedDomain");

    if (newDomain && savedDomain !== newDomain) {
      sessionStorage.setItem("selectedDomain", newDomain);

      sessionStorage.setItem("journeyStarted", "false");
      sessionStorage.setItem("learningStarted", "false");
      sessionStorage.setItem("currentDay", "1");
      sessionStorage.removeItem("roadmapPlan");

      setJourneyStarted(false);
      setLearningStarted(false);
      setCurrentDay(1);
    } else {
      setDomain(newDomain || savedDomain);
      setJourneyStarted(sessionStorage.getItem("journeyStarted") === "true");
      setLearningStarted(sessionStorage.getItem("learningStarted") === "true");
      setCurrentDay(parseInt(sessionStorage.getItem("currentDay") || "1"));
    }

    setDomain(newDomain);
  }, [name]);

  // 🔥 ALL DOMAINS (FULL LIST)
  const topicMap = {

    "ai-and-ml": [
      ["Python Basics → Datatypes, Variables"],
      ["Loops, Conditions"],
      ["Functions"],
      ["NumPy"],
      ["Pandas"],
      ["Visualization"],
      ["Statistics"],
      ["ML Basics"],
      ["Regression"],
      ["Model Evaluation"],
      ["Deep Learning"],
      ["Project"]
    ],

    "web-development": [
      ["HTML"],
      ["CSS"],
      ["Flexbox, Grid"],
      ["JavaScript"],
      ["DOM"],
      ["ES6"],
      ["React"],
      ["Hooks"],
      ["API"],
      ["Node.js"],
      ["MongoDB"],
      ["Project"]
    ],

    "cloud-and-devops": [
      ["Linux Basics"],
      ["Networking"],
      ["Git"],
      ["Docker"],
      ["CI/CD"],
      ["AWS EC2"],
      ["S3"],
      ["Kubernetes"],
      ["Monitoring"],
      ["Security"],
      ["Deployment"],
      ["Project"]
    ],

    "cybersecurity": [
      ["Networking Basics"],
      ["Cryptography"],
      ["Linux Security"],
      ["Web Security"],
      ["OWASP"],
      ["Ethical Hacking"],
      ["Pen Testing"],
      ["Tools"],
      ["Malware"],
      ["Incident Response"],
      ["Auditing"],
      ["Project"]
    ],

    "data-science": [
      ["Python"],
      ["NumPy"],
      ["Pandas"],
      ["Data Cleaning"],
      ["Visualization"],
      ["Statistics"],
      ["EDA"],
      ["ML Basics"],
      ["Regression"],
      ["Classification"],
      ["Projects"],
      ["Deployment"]
    ],

    "mobile-development": [
      ["Programming Basics"],
      ["Java/Kotlin"],
      ["Android Studio"],
      ["UI Design"],
      ["Layouts"],
      ["API Integration"],
      ["Database"],
      ["Firebase"],
      ["Testing"],
      ["Optimization"],
      ["Deployment"],
      ["Project"]
    ],

    "blockchain": [
      ["Blockchain Basics"],
      ["Cryptography"],
      ["Bitcoin"],
      ["Ethereum"],
      ["Smart Contracts"],
      ["Solidity"],
      ["DApps"],
      ["Web3"],
      ["Security"],
      ["Gas Fees"],
      ["Testing"],
      ["Project"]
    ],

    "ui-ux-design": [
      ["Design Principles"],
      ["Color Theory"],
      ["Typography"],
      ["Wireframing"],
      ["Prototyping"],
      ["Figma"],
      ["User Research"],
      ["UX Flow"],
      ["Testing"],
      ["Accessibility"],
      ["Design System"],
      ["Project"]
    ],

    "big-data": [
      ["Big Data Basics"],
      ["Hadoop"],
      ["MapReduce"],
      ["Spark"],
      ["Kafka"],
      ["Data Pipelines"],
      ["ETL"],
      ["Storage"],
      ["Analytics"],
      ["Scaling"],
      ["Cloud Data"],
      ["Project"]
    ],

    "networking": [
      ["OSI Model"],
      ["TCP/IP"],
      ["IP Addressing"],
      ["Routing"],
      ["Switching"],
      ["DNS"],
      ["HTTP/HTTPS"],
      ["Firewalls"],
      ["Security"],
      ["Troubleshooting"],
      ["Tools"],
      ["Project"]
    ]
  };

  const topics = topicMap[domain] || [["Basics"]];

  // ✅ SMART PLAN (NO REPEAT)
  const generatePlan = () => {
    const flatTopics = topics.flat();
    const plan = [];

    let index = 0;

    while (index < flatTopics.length) {
      const daily = [];
      const count = 3 + (plan.length % 2);

      for (let i = 0; i < count; i++) {
        if (index < flatTopics.length) {
          daily.push(flatTopics[index]);
          index++;
        }
      }

      plan.push(daily);
    }

    return plan;
  };

  // ✅ STORE PLAN
  useEffect(() => {
    if (!sessionStorage.getItem("roadmapPlan") && domain) {
      const plan = generatePlan();
      sessionStorage.setItem("roadmapPlan", JSON.stringify(plan));
    }
  }, [domain]);

  const roadmapPlan = JSON.parse(
    sessionStorage.getItem("roadmapPlan") || "[]"
  );

  const getTasksForDay = (day) => {
    return roadmapPlan[day - 1] || [];
  };

  const handleStartJourney = () => {
    sessionStorage.setItem("journeyStarted", "true");
    setJourneyStarted(true);
  };

  const handleStartToday = () => {
    sessionStorage.setItem("learningStarted", "true");
    setLearningStarted(true);
  };

  const progress = roadmapPlan.length
    ? (currentDay / roadmapPlan.length) * 100
    : 0;

  return (
    <div className="space-y-8">
      <Card title="Learning Roadmap">

        {/* HEADER */}
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold capitalize">
            🚀 {domain?.replaceAll("-", " ")} Roadmap
          </h2>
          <span className="text-sm text-gray-400">{timeline}</span>
        </div>

        {/* START */}
        {!journeyStarted && (
          <div className="text-center p-8">
            <h2 className="text-2xl font-bold mb-4">
              Start Your Learning Journey 🚀
            </h2>

            {/* ALL TASKS */}
            <div className="grid gap-3">
              {topics.map((t, i) => (
                <div key={i} className="p-4 bg-slate-800 rounded-xl">
                  Step {i + 1} → {t.join(", ")}
                </div>
              ))}
            </div>

            <button
              onClick={handleStartJourney}
              className="mt-6 px-6 py-3 bg-gradient-to-r from-green-400 to-blue-500 text-white rounded-xl"
            >
              Start Journey
            </button>
          </div>
        )}

        {/* START TODAY */}
        {journeyStarted && !learningStarted && (
          <div className="text-center">
            <button
              onClick={handleStartToday}
              className="px-6 py-3 bg-teal-600 text-white rounded-xl"
            >
              Start From Today 📅
            </button>
          </div>
        )}

        {/* MAIN */}
        {learningStarted && (
          <>
            <div className="flex justify-between bg-slate-800 p-4 rounded-xl">
              <div>
                <h2 className="text-xl font-bold">Day {currentDay}</h2>
                <p className="text-gray-400">
                  {roadmapPlan.length - currentDay} days remaining
                </p>
              </div>

              <div>
                <p>Progress</p>
                <p>{Math.floor(progress)}%</p>
              </div>
            </div>

            {/* PROGRESS BAR */}
            <div className="mt-4 bg-slate-700 h-3 rounded-full">
              <div
                className="h-3 rounded-full"
                style={{
                  width: `${progress}%`,
                  background: "linear-gradient(90deg, #22c55e, #4f46e5)"
                }}
              />
            </div>

            {/* TASKS */}
            <div className="grid md:grid-cols-2 gap-4 mt-6">
              {getTasksForDay(currentDay).map((task, i) => (
                <div key={i} className="p-4 bg-slate-800 rounded-xl">
                  ✔ {task}
                </div>
              ))}
            </div>

            <Link to="/tasks">
              <button className="mt-6 px-6 py-3 bg-teal-500 text-white rounded-xl">
                Go to Tasks →
              </button>
            </Link>
          </>
        )}

      </Card>
    </div>
  );
}
